	assert.equal((await Pool.query('SELECT * FROM likes WHERE user_id=$1 AND video_id=$2', [Owner.id, VideoId])).rowCount, 0);
	assert.equal((await Item()).digged, false); assert.equal((await Item()).stats.diggCount, 0);
