test('direct message reactions and replies use the client\'s own commands, push to the chat, and stay with the message', async () => {
	const Alpha = await CreateUser(Pool, { username: 'react_alpha', password: Password }, 'closed', true);
	const Beta = await CreateUser(Pool, { username: 'react_beta', password: Password }, 'closed', true);
	await CreateUser(Pool, { username: 'react_gamma', password: Password }, 'closed', true);
	await Pool.query('INSERT INTO follows(follower_id, following_id) VALUES ($1, $2), ($2, $1)', [Alpha.id, Beta.id]);
	const Session = async Name => { const Signed = await Login(Pool, Name, Password); return { cookie: `kittok_session=${Signed.Token}`, 'x-csrf-token': Signed.Csrf }; };
	const AsAlpha = await Session('react_alpha'), AsBeta = await Session('react_beta'), AsGamma = await Session('react_gamma');
	const Im = async (Headers, Cmd, Field, Body) => Proto.Decode('Response', Buffer.from(await (await fetch(`${Origin}/v1/kittok`, { method: 'POST', headers: { ...Headers, 'content-type': 'application/x-protobuf' }, body: Proto.Encode('Request', { cmd: Cmd, sequence_id: '1', inbox_type: 0, body: { [Field]: Body } }) })).arrayBuffer()));
	const Chat = (await Im(AsAlpha, 609, 'create_conversation_v2_body', { conversation_type: 1, participants: [Beta.id] })).body.create_conversation_v2_body.conversation;
	const Sent = (await Im(AsAlpha, 100, 'send_message_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, message_type: 7, content: '{"aweType":0,"text":"react to me"}', client_message_id: 'react-1' })).body.send_message_body;
	const Socket = new WebSocket(Origin.replace('http', 'ws') + '/ws/v2', { protocols: ['pbbp2'], headers: { ...AsAlpha, origin: Origin } });
	Socket.binaryType = 'arraybuffer';
	const Received = [];
	Socket.onmessage = Event => Received.push(Event.data);
	await new Promise((Resolve, Reject) => { Socket.onopen = Resolve; Socket.onerror = Reject; });
	const React = (Headers, Contents) => Im(Headers, 705, 'modify_message_property_body', { property_list: { conversation_id: Chat.conversation_id, conversation_short_id: Chat.conversation_short_id, conversation_type: 1, server_message_id: Sent.server_message_id, client_message_id: 'react-1', modify_property_content: Contents } });
	const Done = await React(AsBeta, [{ operation: 0, key: 'e:❤️', value: '', idempotent_id: 'anything' }]);
	assert.equal(Done.status_code, 0); assert.equal(Done.body.modify_message_property_body.status, 0); assert.equal(Done.body.modify_message_property_body.version, '1');
	await new Promise(Resolve => setTimeout(Resolve, 200));
	const Pushes = Received.filter(Data => typeof Data !== 'string').map(Data => Proto.Decode('Response', Proto.Decode('Frame', new Uint8Array(Data)).payload)).filter(Push => Push.cmd === 500);
	const Update = Pushes.at(-1).body.has_new_message_notify.message;
	assert.equal(Update.message_type, 70002); assert.equal(Update.ext['s:client_message_id'], 'react-1'); assert.equal(Update.version, '1');
	assert.deepEqual(Update.property_list['e:❤️'].Items.map(Item => [Item.uid, Item.idempotent_id]), [[Beta.id, Beta.id]]);
	Socket.close();
	const Thread = async Headers => (await Im(Headers, 301, 'messages_in_conversation_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, direction: 1, anchor_index: '0', limit: 20 })).body.messages_in_conversation_body.messages;
	assert.deepEqual(Object.keys((await Thread(AsAlpha)).find(Message => Message.server_message_id === Sent.server_message_id).property_list), ['e:❤️']);
	await React(AsAlpha, [{ operation: 0, key: 'e:👍', value: '' }]);
	assert.equal((await React(AsBeta, [{ operation: 1, key: 'e:👍', value: '', idempotent_id: Alpha.id }])).body.modify_message_property_body.status, 0);
	assert.deepEqual(Object.keys((await Thread(AsBeta)).find(Message => Message.server_message_id === Sent.server_message_id).property_list).sort(), ['e:❤️', 'e:👍'].sort());
	await React(AsBeta, [{ operation: 1, key: 'e:❤️', value: '' }]);
	assert.deepEqual(Object.keys((await Thread(AsAlpha)).find(Message => Message.server_message_id === Sent.server_message_id).property_list), ['e:👍']);
	assert.notEqual((await React(AsGamma, [{ operation: 0, key: 'e:😂', value: '' }])).status_code, 0);
	assert.equal((await React(AsBeta, [{ operation: 0, key: 'nope', value: '' }])).body.modify_message_property_body.status, 2);
	assert.equal((await React(AsBeta, [{ operation: 5, key: 'e:😂', value: '' }])).body.modify_message_property_body.status, 2);
	assert.equal((await React(AsBeta, ['😂', '😭', '😡', '🎉'].map(Emoji => ({ operation: 0, key: `e:${Emoji}`, value: '' })))).body.modify_message_property_body.status, 2);
	await Pool.query('INSERT INTO blocks(blocker_id, blocked_id) VALUES ($1, $2)', [Alpha.id, Beta.id]);
	assert.equal((await React(AsBeta, [{ operation: 0, key: 'e:😂', value: '' }])).body.modify_message_property_body.status, 3);
	await Pool.query('DELETE FROM blocks WHERE blocker_id = $1', [Alpha.id]);
	const Reply = async (Id, Quote) => (await Im(AsBeta, 100, 'send_message_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, message_type: 7, content: '{"aweType":703,"text":"replying"}', client_message_id: Id, ref_msg_info: { referenced_message_id: Quote, hint: 'react to me' } })).body.send_message_body;
	const Answer = await Reply('reply-1', Sent.server_message_id);
	const Quoted = async () => (await Thread(AsAlpha)).find(Message => Message.server_message_id === Answer.server_message_id).reference_info;
	assert.deepEqual(await Quoted(), { referenced_message_id: Sent.server_message_id, hint: 'react to me', ref_message_type: '7', referenced_message_status: 0, root_message_id: Sent.server_message_id, root_message_conv_index: '1', sender: Alpha.id });
	await Pool.query("UPDATE messages SET recalled_at = now() WHERE id = $1", [Sent.server_message_id]);
	assert.equal((await Quoted()).referenced_message_status, 3);
	await Pool.query("UPDATE messages SET recalled_at = NULL WHERE id = $1", [Sent.server_message_id]);
	const Elsewhere = (await Im(AsGamma, 609, 'create_conversation_v2_body', { conversation_type: 1, participants: [Alpha.id] })).body.create_conversation_v2_body;
	const Outside = (await Im(AsAlpha, 100, 'send_message_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, message_type: 7, content: '{"aweType":703,"text":"bad quote"}', client_message_id: 'reply-2', ref_msg_info: { referenced_message_id: '1' } })).body.send_message_body;
	assert.equal((await Thread(AsAlpha)).find(Message => Message.server_message_id === Outside.server_message_id).reference_info, undefined);
	assert.ok(Elsewhere);
	const Settings = (await (await Call('/_kittok/admin/settings', 'GET', undefined, Auth())).json()).misc;
	assert.equal((await Call('/_kittok/admin/settings/misc', 'POST', { value: { ...Settings, messageReactions: false } }, Auth())).status, 200);
	assert.equal((await React(AsBeta, [{ operation: 0, key: 'e:😂', value: '' }])).body.modify_message_property_body.status, 3);
	assert.equal((await Call('/_kittok/admin/settings/misc', 'POST', { value: Settings }, Auth())).status, 200);
});

test('deactivating hides an account until its owner logs back in, and deletion requests run out after 30 days', async () => {
	const Leaver = await CreateUser(Pool, { username: 'leaver', password: Password, email: 'leaver@example.com' }, 'closed', true);
	const Signed = await Login(Pool, 'leaver', Password);
	const As = { cookie: `kittok_session=${Signed.Token}`, 'x-csrf-token': Signed.Csrf };
	const Page = await fetch(`${Origin}/tpp/inapp/pns_product_poseidon/account_deactivate_webapp.html?isDark=1`, { headers: { cookie: As.cookie } });
	assert.equal(Page.status, 200); assert.match(Page.headers.get('content-security-policy'), /frame-ancestors 'self'/);
	const Html = await Page.text(); assert.ok(Html.includes('Deactivate account?') && Html.includes(Signed.Csrf));
	assert.ok((await (await fetch(`${Origin}/tpp/inapp/pns_product_poseidon/account_delete_new_webapp.html`)).text()).includes('Log in to continue'));
	assert.equal((await fetch(`${Origin}/tpp/inapp/pns_product_poseidon/other.html`, { headers: { cookie: As.cookie } })).status, 404);
	assert.ok((await (await Call('/tiktok/pns/bff/account/questionnaire/config')).json()).questionnaireOptions.length >= 3);
	const Deactivate = (Body, Headers = As) => Call('/api/v1/account/deactivate', 'POST', Body, Headers);
	assert.equal((await Deactivate({ password: Password }, { cookie: As.cookie })).status, 403);
	assert.equal((await (await Deactivate({ password: 'wrong-password-here' })).json()).error, 'InvalidPassword');
	assert.equal((await Pool.query("SELECT count(*)::int AS admins FROM users WHERE role = 'admin' AND suspended_at IS NULL")).rows[0].admins, 1);
	assert.equal((await (await Deactivate({ password: Password }, Auth())).json()).error, 'LastAdmin');
	const Done = await Deactivate({ password: Password });
	assert.equal(Done.status, 200); assert.equal((await Done.json()).deleteAfter, null);
	assert.equal((await Pool.query('SELECT count(*)::int AS live FROM sessions WHERE user_id = $1', [Leaver.id])).rows[0].live, 0);
	assert.equal((await Call('/api/user/detail/?uniqueId=leaver')).status, 404);
	assert.ok(!(await (await Call('/api/search/user/full/?keyword=leaver')).json()).user_list.length);
	assert.equal((await fetch(`${Origin}/logout`, { redirect: 'manual' })).headers.get('location'), '/');
	const Back = await Login(Pool, 'leaver', Password);
	assert.ok(Back.Token); assert.equal((await Call('/api/user/detail/?uniqueId=leaver')).status, 200);
	assert.deepEqual((await Pool.query("SELECT kind FROM user_events WHERE user_id = $1 AND kind IN ('deactivated', 'reactivated') ORDER BY id", [Leaver.id])).rows.map(Row => Row.kind), ['deactivated', 'reactivated']);
	const AsBack = { cookie: `kittok_session=${Back.Token}`, 'x-csrf-token': Back.Csrf };
	await Pool.query("INSERT INTO invites(token_hash, created_by, expires_at) VALUES ($1, $2, now() + interval '1 day')", [Hash(Token()), Leaver.id]);
	await Pool.query("INSERT INTO videos(author_id, description, file_name, cover_name, width, height, duration, bytes) VALUES ($1, 'bye', 'leaver-test.mp4', 'leaver-test.jpg', 1, 1, 1, 1)", [Leaver.id]);
	const Scheduled = await (await Deactivate({ password: Password, delete: true }, AsBack)).json();
	assert.ok(new Date(Scheduled.deleteAfter) - Date.now() > 29 * 86400000);
	assert.equal(await DeleteExpiredAccounts(Pool, Config), 0);
	await Pool.query("UPDATE users SET delete_after = now() - interval '1 minute' WHERE id = $1", [Leaver.id]);
	assert.equal(await DeleteExpiredAccounts(Pool, Config), 1);
	assert.equal((await Pool.query('SELECT count(*)::int AS left FROM users WHERE id = $1', [Leaver.id])).rows[0].left, 0);
	assert.equal((await Pool.query('SELECT count(*)::int AS left FROM videos WHERE author_id = $1', [Leaver.id])).rows[0].left, 0);
	const Banned = await CreateUser(Pool, { username: 'banned_leaver', password: Password }, 'closed', true);
	await Pool.query('UPDATE users SET deactivated_at = now(), suspended_at = now() WHERE id = $1', [Banned.id]);
	assert.equal((await Call(`/_kittok/admin/users/${Banned.id}/suspend`, 'POST', { category: 'spam', reason: 'Banned while deactivated' }, Auth())).status, 200);
	await assert.rejects(Login(Pool, 'banned_leaver', Password), /AccountSuspended/);
});

test('download your data builds a TXT or JSON archive with your own videos after a password check', async () => {
	const Saver = await CreateUser(Pool, { username: 'saver', password: Password }, 'closed', true);
	const Signed = await Login(Pool, 'saver', Password);
	const As = { cookie: `kittok_session=${Signed.Token}`, 'x-csrf-token': Signed.Csrf };
	await Pool.query('INSERT INTO likes(user_id, video_id) VALUES ($1, $2)', [Saver.id, VideoId]);
	const Html = await (await fetch(`${Origin}/ppp?lang=en&isDark=false&_pia_=1`, { headers: { cookie: As.cookie } })).text();
	assert.ok(Html.includes('Download your data') && Html.includes('No files yet'));
	const Ask = Body => Call('/api/v1/account/data', 'POST', Body, As);
	assert.equal((await Ask({ format: 'pdf' })).status, 400);
	assert.equal((await Ask({ format: 'json', sections: ['nope'] })).status, 400);
	const Json = await (await Ask({ format: 'json', sections: ['profile', 'activity'] })).json();
	const Txt = await (await Ask({ format: 'txt' })).json();
	assert.ok((await (await fetch(`${Origin}/ppp?tab=download`, { headers: { cookie: As.cookie } })).text()).includes(`data-download="${Txt.id}"`));
	const Fetch = (Id, Secret) => fetch(`${Origin}/api/v1/account/data/download`, { method: 'POST', redirect: 'manual', headers: { cookie: As.cookie, 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ id: Id, csrf: Signed.Csrf, password: Secret, isDark: 'false' }) });
	assert.match((await Fetch(Json.id, 'wrong-password-here')).headers.get('location'), /error=InvalidPassword/);
	assert.match((await Fetch('999999999', Password)).headers.get('location'), /error=ExportExpired/);
	const Unzip = Bytes => {
		const Files = {}; let At = Bytes.readUInt32LE(Bytes.length - 6);
		while (Bytes.readUInt32LE(At) === 0x02014b50) {
			const [Method, Packed, NameLength, ExtraLength, CommentLength, Local] = [Bytes.readUInt16LE(At + 10), Bytes.readUInt32LE(At + 20), Bytes.readUInt16LE(At + 28), Bytes.readUInt16LE(At + 30), Bytes.readUInt16LE(At + 32), Bytes.readUInt32LE(At + 42)];
			const Start = Local + 30 + Bytes.readUInt16LE(Local + 26) + Bytes.readUInt16LE(Local + 28), Data = Bytes.subarray(Start, Start + Packed);
			Files[Bytes.toString('utf8', At + 46, At + 46 + NameLength)] = Method === 8 ? inflateRawSync(Data) : Data;
			At += 46 + NameLength + ExtraLength + CommentLength;
		}
		return Files;
	};
	const Got = await Fetch(Json.id, Password);
	assert.equal(Got.headers.get('content-type'), 'application/zip'); assert.match(Got.headers.get('content-disposition'), /attachment; filename="Kittok_Data_\d+\.zip"/);
	const Data = JSON.parse(Unzip(Buffer.from(await Got.arrayBuffer()))['user_data.json']);
	assert.deepEqual(Object.keys(Data), ['Profile', 'Activity']);
	assert.equal(Data.Profile['Profile Information'].ProfileMap.userName, 'saver');
	assert.equal(Data.Activity['Like List'].ItemFavoriteList[0].Link, `${Origin}/@owner/video/${VideoId}`);
	const Mine = await (await Call(`/api/user/detail/?uniqueId=owner`)).json();
	const AsOwner = { cookie: Cookie };
	const OwnerExport = await (await Call('/api/v1/account/data', 'POST', { format: 'txt', sections: ['video', 'settings'] }, Auth())).json();
	const OwnerZip = await fetch(`${Origin}/api/v1/account/data/download`, { method: 'POST', headers: { ...AsOwner, 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ id: OwnerExport.id, csrf: Session.csrfToken, password: Password }) });
	const Files = Unzip(Buffer.from(await OwnerZip.arrayBuffer()));
	assert.ok(Mine.userInfo.user.uniqueId === 'owner' && Files['Video/Videos.txt'].toString().includes(`Link: ${Origin}/@owner/video/${VideoId}`));
	assert.ok(Files[`Video/Videos/${VideoId}.mp4`].length > 1000 && Files['App Settings/Settings.txt'].toString().includes('Private Account: '));
	assert.deepEqual((await Pool.query("SELECT kind FROM user_events WHERE user_id = $1 AND kind LIKE 'data_%' ORDER BY id", [Saver.id])).rows.map(Row => Row.kind), ['data_requested', 'data_requested', 'data_downloaded']);
	for (let Index = 0; Index < 3; Index++) await Ask({ format: 'txt' });
	assert.equal((await Pool.query('SELECT count(*)::int AS kept FROM data_exports WHERE user_id = $1', [Saver.id])).rows[0].kept, 3);
	assert.equal((await Ask({ format: 'txt' })).status, 429);
});

test('photo and video messages upload through Kittok, render as native cards, and only reach the chat', async () => {
	const Alpha = await CreateUser(Pool, { username: 'media_alpha', password: Password }, 'closed', true);
	const Beta = await CreateUser(Pool, { username: 'media_beta', password: Password }, 'closed', true);
	await CreateUser(Pool, { username: 'media_gamma', password: Password }, 'closed', true);
	await Pool.query('INSERT INTO follows(follower_id, following_id) VALUES ($1, $2), ($2, $1)', [Alpha.id, Beta.id]);
	const Session = async Name => { const Signed = await Login(Pool, Name, Password); return { cookie: `kittok_session=${Signed.Token}`, 'x-csrf-token': Signed.Csrf }; };
	const AsAlpha = await Session('media_alpha'), AsBeta = await Session('media_beta'), AsGamma = await Session('media_gamma');
	const Im = async (Headers, Cmd, Field, Body) => Proto.Decode('Response', Buffer.from(await (await fetch(`${Origin}/v1/kittok`, { method: 'POST', headers: { ...Headers, 'content-type': 'application/x-protobuf' }, body: Proto.Encode('Request', { cmd: Cmd, sequence_id: '1', inbox_type: 0, body: { [Field]: Body } }) })).arrayBuffer()));
	assert.equal((await Im(AsAlpha, 2059, 'media_upload_config_request_body', {})).body.media_upload_config_response_body.configs.length, 2);
	const Photo = join(Directory, 'dm-photo.png'), Clip = join(Directory, 'dm-clip.mp4');
	assert.equal(spawnSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', 'color=c=red:s=64x48', '-frames:v', '1', Photo]).status, 0);
	assert.equal(spawnSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', 'testsrc2=size=96x160:rate=12:duration=1', '-c:v', 'libx264', '-threads', '1', '-pix_fmt', 'yuv420p', Clip]).status, 0);
	const Upload = (Headers, Type, File) => readFile(File).then(Bytes => fetch(`${Origin}/api/v1/im/media?type=${Type}`, { method: 'POST', headers: { ...Headers, 'content-type': 'application/octet-stream' }, body: Bytes }));
	assert.equal((await Upload({ cookie: AsAlpha.cookie }, 'image', Photo)).status, 403);
	const Image = await (await Upload(AsAlpha, 'image', Photo)).json();
	assert.match(Image.uri, /^dm-[0-9a-f-]{36}$/); assert.deepEqual([Image.width, Image.height], [64, 48]);
	const Media = (Headers, Path) => fetch(`${Origin}/api/v1/im/media/${Path}`, { headers: { cookie: Headers.cookie } });
	assert.equal((await Media(AsAlpha, Image.uri)).headers.get('content-type'), 'image/jpeg');
	assert.equal((await Media(AsBeta, Image.uri)).status, 404);
	const Chat = (await Im(AsAlpha, 609, 'create_conversation_v2_body', { conversation_type: 1, participants: [Beta.id] })).body.create_conversation_v2_body.conversation;
	const Send = (Headers, Type, Id, Uri) => Im(Headers, 100, 'send_message_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, message_type: Type, content: '""', client_message_id: Id, send_media_list: Uri ? [{ type: 1, id: Uri }] : [] });
	assert.equal((await Send(AsAlpha, 1802, 'media-0')).status_code, 4);
	const Sent = (await Send(AsAlpha, 1802, 'media-1', Image.uri)).body.send_message_body;
	assert.equal(Sent.status, 0);
	assert.equal((await Send(AsAlpha, 1802, 'media-2', Image.uri)).status_code, 4);
	assert.equal((await Send(AsBeta, 1802, 'media-3', Image.uri)).status_code, 4);
	const Thread = async Headers => (await Im(Headers, 301, 'messages_in_conversation_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, direction: 1, anchor_index: '0', limit: 20 })).body.messages_in_conversation_body.messages;
	const Received = (await Thread(AsBeta)).find(Message => Message.server_message_id === Sent.server_message_id);
	const Card = Proto.Decode('MessageContent', Received.content_pb).picture_card;
	assert.equal(Card.image.url_list[0], `/api/v1/im/media/${Image.uri}`); assert.deepEqual(Card.image.resolution, { width: 64, height: 48 });
	assert.equal(Received.ext['a:moderation_result'], '2');
	assert.equal((await Media(AsBeta, Image.uri)).status, 200);
	assert.equal((await Media(AsGamma, Image.uri)).status, 404);
	const Video = await (await Upload(AsBeta, 'video', Clip)).json();
	assert.ok(Video.cover.endsWith('/cover') && Video.duration > 0);
	const Reply = (await Send(AsBeta, 1803, 'media-4', Video.uri)).body.send_message_body;
	const Movie = Proto.Decode('MessageContent', (await Thread(AsAlpha)).find(Message => Message.server_message_id === Reply.server_message_id).content_pb).video_card.video;
	assert.equal(JSON.parse(Movie.video_model).video_list[0].main_url, `/api/v1/im/media/${Video.uri}`);
	assert.equal((await Media(AsAlpha, Movie.cover.url_list[0].split('/media/')[1])).headers.get('content-type'), 'image/jpeg');
	assert.equal((await fetch(`${Origin}/api/v1/im/media/${Video.uri}`, { headers: { cookie: AsAlpha.cookie, range: 'bytes=0-9' } })).status, 206);
	assert.equal((await Media(AsGamma, `${Video.uri}?review=1`)).status, 404);
	assert.equal((await (await Call(`/aweme/v2/aweme/feedback/?${new URLSearchParams({ report_type: 'im', reason: 102, object_id: Chat.conversation_short_id, owner_id: Beta.id, msg_list: `${Reply.server_message_id},1` })}`, 'GET', undefined, AsAlpha)).json()).status_code, 0);
	const Ticket = (await (await Call('/_kittok/admin/tickets?type=message', 'GET', undefined, Auth())).json()).tickets.find(Row => Row.id === Reply.server_message_id);
	assert.equal(Ticket.preview, '[Video]'); assert.equal(Ticket.thumb, `${Origin}/api/v1/im/media/${Video.uri}/cover?review=1`);
	const Review = await (await Call(`/_kittok/admin/tickets/message/${Reply.server_message_id}`, 'GET', undefined, Auth())).json();
	const Shown = Review.content.thread.find(Row => Row.id === Reply.server_message_id).media;
	assert.equal(Shown.kind, 'video'); assert.equal((await fetch(Shown.url, { headers: { cookie: Cookie } })).status, 200);
	assert.equal((await fetch(Review.content.thread.find(Row => Row.id === Sent.server_message_id).media.url, { headers: { cookie: Cookie } })).status, 200);
	assert.equal((await Media(AsGamma, `${Video.uri}?review=1`)).status, 404);
	assert.equal((await Im(AsAlpha, 702, 'recall_message_body', { conversation_short_id: Chat.conversation_short_id, conversation_type: 1, server_message_id: Sent.server_message_id })).status_code, 0);
	assert.equal((await Media(AsBeta, Image.uri)).status, 404);
	assert.equal((await Thread(AsBeta)).find(Message => Message.server_message_id === Sent.server_message_id).content_pb, undefined);
	const Shim = (await MessageUploader(Buffer.from('(self.__LOADABLE_LOADED_CHUNKS__=self.__LOADABLE_LOADED_CHUNKS__||[]).push([["9"],{42:function(e){e.exports=0}}]);'))).toString();
	assert.ok(Shim.startsWith('(self.__LOADABLE_LOADED_CHUNKS__=self.__LOADABLE_LOADED_CHUNKS__||[]).push([["9"],{42:function(e){e.exports=class KittokUploader'));
	assert.ok(Shell(await readFile(join(ClientDir, 'index.html'), 'utf8'), Origin, { Config, User: { ...Alpha, csrf_token: AsAlpha['x-csrf-token'] } }).includes('"web_dm_multimedia_msg":{"vid":"v2"'));
});

test('group chats are made of friends, live in the group inbox, and post native notices as people join, leave, and rename', async () => {
	const Users = {}, As = {};
	for (const Name of ['grp_a', 'grp_b', 'grp_c', 'grp_d', 'grp_x']) {
		Users[Name] = await CreateUser(Pool, { username: Name, displayName: Name.toUpperCase(), password: Password }, 'closed', true);
		const Signed = await Login(Pool, Name, Password);
		As[Name] = { cookie: `kittok_session=${Signed.Token}`, 'x-csrf-token': Signed.Csrf };
	}
	for (const A of ['grp_a', 'grp_b', 'grp_c', 'grp_d']) for (const B of ['grp_a', 'grp_b', 'grp_c', 'grp_d']) if (A !== B) await Pool.query('INSERT INTO follows(follower_id, following_id) VALUES ($1, $2)', [Users[A].id, Users[B].id]);
	const Im = async (Headers, Cmd, Field, Body, Inbox = 1) => Proto.Decode('Response', Buffer.from(await (await fetch(`${Origin}/v1/kittok`, { method: 'POST', headers: { ...Headers, 'content-type': 'application/x-protobuf' }, body: Proto.Encode('Request', { cmd: Cmd, sequence_id: '1', inbox_type: Inbox, body: { [Field]: Body } }) })).arrayBuffer()));
	const Create = (Headers, Participants, Name) => Im(Headers, 609, 'create_conversation_v2_body', { conversation_type: 2, participants: Participants, name: Name });
	assert.equal((await Create(As.grp_a, [Users.grp_b.id, Users.grp_x.id])).status_code, 11);
	assert.equal((await Create(As.grp_a, [Users.grp_b.id])).status_code, 4);
	const Group = (await Create(As.grp_a, [Users.grp_b.id, Users.grp_c.id], 'Crew')).body.create_conversation_v2_body.conversation;
	assert.deepEqual([Group.conversation_type, Group.inbox_type, Group.conversation_core_info.name, Group.participants_count], [2, 1, 'Crew', 3]);
	assert.equal(Group.first_page_participants.participants.find(Member => Member.role === 1).user_id, Users.grp_a.id);
	const Short = Group.conversation_short_id, Target = { conversation_short_id: Short, conversation_type: 2 };
	const Thread = async Headers => (await Im(Headers, 301, 'messages_in_conversation_body', { ...Target, direction: 1, anchor_index: '0', limit: 50 })).body.messages_in_conversation_body?.messages;
	const Notices = async Headers => (await Thread(Headers)).filter(Message => Message.message_type === 1031).map(Message => JSON.parse(Message.content).aweType);
	const List = async (Headers, Inbox) => ((await Im(Headers, 2006, 'get_user_conversation_list_body', { limit: 50 }, Inbox)).body.get_conversation_list_body?.list ?? []).map(Room => Room.conversation_short_id);
	assert.ok((await List(As.grp_b, 1)).includes(Short)); assert.ok(!(await List(As.grp_b, 0)).includes(Short));
	const Sent = (await Im(As.grp_b, 100, 'send_message_body', { ...Target, message_type: 7, content: '{"aweType":0,"text":"hi crew"}', client_message_id: 'grp-1' })).body.send_message_body;
	assert.equal(Sent.status, 0);
	assert.ok((await Thread(As.grp_c)).some(Message => Message.server_message_id === Sent.server_message_id));
	assert.equal((await Im(As.grp_d, 301, 'messages_in_conversation_body', Target)).status_code, 1001);
	const Added = (await Im(As.grp_b, 650, 'conversation_add_participants_body', { ...Target, participants: [Users.grp_d.id, Users.grp_x.id] })).body.conversation_add_participants_body;
	assert.deepEqual([Added.success_participants, Added.failed_participants], [[Users.grp_d.id], [Users.grp_x.id]]);
	assert.ok((await Thread(As.grp_d)).some(Message => Message.server_message_id === Sent.server_message_id));
	const Socket = new WebSocket(Origin.replace('http', 'ws') + '/ws/v2', { protocols: ['pbbp2'], headers: { ...As.grp_c, origin: Origin } });
	Socket.binaryType = 'arraybuffer';
	const Received = [];
	Socket.onmessage = Event => Received.push(Event.data);
	await new Promise((Resolve, Reject) => { Socket.onopen = Resolve; Socket.onerror = Reject; });
	const Commands = () => Received.filter(Data => typeof Data !== 'string').map(Data => Proto.Decode('Response', Proto.Decode('Frame', new Uint8Array(Data)).payload))
		.filter(Push => Push.cmd === 500 && Push.inbox_type === 1).map(Push => Push.body.has_new_message_notify.message).filter(Message => Message.message_type === 50001).map(Message => JSON.parse(Message.content));
	assert.equal((await Im(As.grp_b, 651, 'conversation_remove_participants_body', { ...Target, participants: [Users.grp_c.id] })).status_code, 11);
	assert.equal((await Im(As.grp_a, 651, 'conversation_remove_participants_body', { ...Target, participants: [Users.grp_c.id] })).status_code, 0);
	assert.equal((await Im(As.grp_c, 301, 'messages_in_conversation_body', Target)).status_code, 1001);
	await new Promise(Resolve => setTimeout(Resolve, 200));
	assert.deepEqual(Commands().map(Command => Command.command_type), [7, 6]);
	assert.deepEqual(Commands()[0].removed_participant, [Users.grp_c.id]); assert.ok(Commands()[1].group_version >= 3);
	Socket.close();
	assert.equal((await Im(As.grp_d, 902, 'set_conversation_core_info_body', { ...Target, name: 'Crew 2', is_name_set: true })).body.set_conversation_core_info_body.conversation_core_info.name, 'Crew 2');
	assert.equal((await Im(As.grp_a, 652, 'leave_conversation_body', Target)).status_code, 0);
	const Info = await (await Call(`/api/v1/im/groups/${Short}`, 'GET', undefined, As.grp_b)).json();
	assert.equal(Info.owner, Users.grp_b.id); assert.deepEqual(Info.members.map(Member => Member.username).sort(), ['grp_b', 'grp_d']);
	assert.deepEqual((await Notices(As.grp_b)).reverse(), [103112, 103105, 103102, 103106, 103104]);
	assert.equal((await Call('/api/v1/im/groups', 'POST', { members: [Users.grp_c.id, Users.grp_d.id] }, { cookie: As.grp_b.cookie })).status, 403);
	assert.equal((await Call('/api/v1/im/groups', 'POST', { members: [Users.grp_c.id, Users.grp_d.id], name: 'Two' }, As.grp_b)).status, 200);
	assert.deepEqual((await (await Call('/api/v1/im/groups', 'GET', undefined, As.grp_c)).json()).groups.map(Room => Room.title), ['Two']);
	assert.deepEqual((await (await Call('/api/v1/im/groups/friends', 'GET', undefined, As.grp_x)).json()).friends, []);
	assert.equal((await Call(`/api/v1/im/groups/${Short}/members/${Users.grp_d.id}`, 'DELETE', undefined, { cookie: As.grp_d.cookie })).status, 403);
});

test('download video saves a copy marked with the logo and @username plus an end card, kept for next time, and follows the Downloads switch', async () => {
	const Detail = async Headers => (await (await Call(`/api/item/detail/?itemId=${VideoId}`, 'GET', undefined, Headers)).json()).itemInfo.itemStruct;
	const Item = await Detail({});
	assert.deepEqual([Item.video.downloadAddr, Item.downloadSetting, Item.authorPrivate, Item.author.downloadSetting], [`${Origin}/api/v1/videos/${VideoId}/download`, 0, false, 0]);
	const First = await fetch(Item.video.downloadAddr);
	assert.equal(First.status, 200); assert.equal(First.headers.get('content-type'), 'video/mp4'); assert.match(First.headers.get('content-disposition'), /attachment; filename="owner_\d+\.mp4"/);
	const Saved = join(Directory, 'downloaded.mp4');
	await writeFile(Saved, Buffer.from(await First.arrayBuffer()));
	const Probe = spawnSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', Saved], { encoding: 'utf8' });
	const Source = (await Pool.query('SELECT duration, download_name FROM videos WHERE id = $1', [VideoId])).rows[0];
	assert.ok(Number(Probe.stdout) > Source.duration + 2.3, `duration ${Probe.stdout}`);
	assert.match(Source.download_name, new RegExp(`^dl-${VideoId}-[0-9a-f]{16}\\.mp4$`));
	assert.equal((await fetch(Item.video.downloadAddr, { headers: { range: 'bytes=0-15' } })).status, 206);
	const Switch = Value => Call('/api/privacy/user/settings/update/v1', 'POST', { field: 'download', value: Value }, Auth());
	assert.equal((await (await Switch(0)).json()).privacy_settings.download, 0);
	assert.equal((await Detail({})).downloadSetting, 3);
	assert.equal((await fetch(Item.video.downloadAddr)).status, 403);
	assert.equal((await fetch(Item.video.downloadAddr, { headers: { cookie: Cookie } })).status, 200);
	assert.equal((await (await Call('/api/privacy/setting/restriction/v1/', 'GET', undefined, Auth())).json()).privacy_settings.download, 0);
	assert.equal((await (await Switch(1)).json()).privacy_settings.download, 1);
	assert.equal((await fetch(`${Origin}/media/${Source.download_name}`)).status, 404);
});

test('misc switches turn Kittok features off and back on without a restart', async () => {
	const Settings = await (await Call('/_kittok/admin/settings', 'GET', undefined, Auth())).json();
	assert.ok(Object.values(Settings.misc).every(Boolean));
	const Set = Value => Call('/_kittok/admin/settings/misc', 'POST', { value: { ...Settings.misc, ...Value } }, Auth());
	assert.equal((await Call('/_kittok/admin/settings/misc', 'POST', { value: 'nope' }, Auth())).status, 400);
	await Pool.query('UPDATE users SET verified = true WHERE id = $1', [Owner.id]);
	assert.equal((await Set({ verifiedBadges: false, reposts: false, hashtags: false, collections: false, commentLabels: false })).status, 200);
	const Get = async Path => (await Call(Path, 'GET', undefined, Auth())).json();
	assert.equal((await Get('/api/user/detail/?uniqueId=owner')).userInfo.user.verified, false);
	assert.deepEqual((await Get('/_kittok/badges?users=owner')).verified, []);
	assert.ok(!(await Get('/api/share/settings/')).share_platforms.some(Platform => Platform.platform_id === 'repost'));
	assert.equal((await Call(`/tiktok/v1/upvote/publish?item_id=${VideoId}`, 'POST', undefined, Auth())).status, 403);
	assert.equal((await Get('/api/challenge/detail/?challengeName=kittok')).statusCode, 10205);
	const Item = (await Get(`/api/item/detail/?itemId=${VideoId}`)).itemInfo.itemStruct;
	assert.deepEqual([Item.textExtra, Item.challenges], [[], []]);
	assert.equal((await Call('/api/collection/create/?collectionName=Off&collectionStatus=1', 'POST', undefined, Auth())).status, 403);
	assert.ok((await Get(`/api/comment/list/?aweme_id=${VideoId}&count=50&cursor=0`)).comments.every(Comment => Comment.label_type === 0));
	assert.equal((await Set({})).status, 200);
	assert.equal((await Get('/api/user/detail/?uniqueId=owner')).userInfo.user.verified, true);
	assert.equal((await Get('/api/challenge/detail/?challengeName=kittok')).statusCode, 0);
	await Pool.query('UPDATE users SET verified = false WHERE id = $1', [Owner.id]);
});
